import React from "react";
import { motion } from "framer-motion";

const Home = ({ darkMode }) => {
    const services = [
        { title: "Floor Planning", desc: "Strategic space management for maximum flow.", icon: "📐" },
        { title: "Vendor Sourcing", desc: "Connecting you with top-tier booth builders.", icon: "🤝" },
        { title: "Digital Integration", desc: "Hybrid event solutions and custom event apps.", icon: "🌐" },
    ];

    const userRoles = [
        { title: "Exhibitor", desc: "Showcase your brand", color: "from-purple-500 to-indigo-600", icon: "🚀" },
        { title: "Trade Visitor", desc: "Discover innovations", color: "from-blue-500 to-cyan-500", icon: "✨" },
        { title: "Partner/Seller", desc: "Expand your reach", color: "from-emerald-500 to-teal-600", icon: "💎" }
    ];

    return (
        <main>
            {/* Services Section */}
            <section className="py-20 px-8 max-w-7xl mx-auto">
                <div className="grid md:grid-cols-3 gap-8">
                    {services.map((service, index) => (
                        <motion.div
                            key={index}
                            whileHover={{ y: -10 }}
                            className={`p-10 rounded-3xl border ${darkMode ? "bg-gray-800 border-gray-700" : "bg-white border-gray-100"
                                } shadow-2xl transition-all group`}
                        >
                            <div className="text-4xl mb-4 group-hover:scale-125 transition-transform inline-block">{service.icon}</div>
                            <h4 className="text-2xl font-bold mb-3">{service.title}</h4>
                            <p className="opacity-60 leading-relaxed">{service.desc}</p>
                            <motion.div className="mt-6 h-1 w-0 bg-blue-500 group-hover:w-full transition-all duration-500" />
                        </motion.div>
                    ))}
                </div>
            </section>

            {/* Stats Section */}
            <section className={`py-16 ${darkMode ? "bg-gray-800/50" : "bg-blue-600"} text-white text-center`}>
                <div className="grid md:grid-cols-3 gap-10 max-w-5xl mx-auto">
                    {[
                        { val: "500+", label: "Events Managed" },
                        { val: "12M+", label: "Attendees Yearly" },
                        { val: "Global", label: "24 Country Reach" }
                    ].map((stat, i) => (
                        <div key={i}>
                            <div className="text-5xl font-black">{stat.val}</div>
                            <div className="opacity-70">{stat.label}</div>
                        </div>
                    ))}
                </div>
            </section>

            {/* FANCY NEW ACTION BUTTONS SECTION */}
            <section className="py-24 px-8 max-w-7xl mx-auto">
                <h2 className={`text-4xl font-black text-center mb-12 ${darkMode ? 'text-white' : 'text-gray-900'}`}>
                    Join the <span className="text-blue-500">Network</span>
                </h2>
                <div className="grid md:grid-cols-3 gap-6">
                    {userRoles.map((role, idx) => (
                        <motion.button
                            key={idx}
                            whileHover={{ scale: 1.03 }}
                            whileTap={{ scale: 0.97 }}
                            className={`relative overflow-hidden group p-8 rounded-2xl text-left transition-all shadow-lg bg-gradient-to-br ${role.color}`}
                        >
                            {/* Animated Background Blur Circle */}
                            <div className="absolute -right-4 -top-4 w-24 h-24 bg-white/10 rounded-full blur-2xl group-hover:bg-white/20 transition-all" />

                            <div className="relative z-10 flex flex-col h-full justify-between">
                                <div>
                                    <span className="text-3xl mb-4 block">{role.icon}</span>
                                    <h3 className="text-2xl font-bold text-white mb-1">{role.title}</h3>
                                    <p className="text-white/80 text-sm">{role.desc}</p>
                                </div>

                                <div className="mt-8 flex items-center text-white font-bold">
                                    Get Started
                                    <motion.span

                                        animate={{ x: 10 }} transition={{ repeat: Infinity, duration: 1.5 }}
                                        className="ml-2"
                                    >
                                        →
                                    </motion.span>
                                </div>
                            </div>
                        </motion.button>
                    ))}
                </div>
            </section>
        </main>
    );
};

export default Home;
